from pathlib import Path
import re

BASE = "612c238"

bell_path = Path("components/notifications/notification-bell.tsx")
context_path = Path("components/portal/admin-context-panel.tsx")

if not bell_path.exists():
    raise SystemExit("Missing notification bell. Run from repo root.")
if not context_path.exists():
    raise SystemExit("Missing admin context panel. Run from repo root.")

# Full replacement is intentional: the bell is now the notification-state owner.
bell_path.write_text('"use client";\n\nimport Link from "next/link";\nimport { Bell, BellOff } from "lucide-react";\nimport { createPortal } from "react-dom";\nimport { usePathname } from "next/navigation";\nimport {\n  useCallback,\n  useEffect,\n  useMemo,\n  useRef,\n  useState,\n} from "react";\n\nimport { createClient } from "@/lib/supabase/client";\n\ntype NotificationRow = {\n  id: string;\n  type: string;\n  title: string;\n  body: string;\n  href: string | null;\n  starts_at: string;\n  is_automatic: boolean;\n  is_unread: boolean;\n};\n\ntype NotificationBundle = {\n  muted: boolean;\n  notifications: NotificationRow[];\n};\n\nexport function NotificationBell() {\n  const pathname = usePathname();\n  const supabase = useMemo(\n    () => createClient(),\n    [],\n  );\n\n  const rootRef =\n    useRef<HTMLDivElement>(null);\n  const buttonRef =\n    useRef<HTMLButtonElement>(null);\n  const panelRef =\n    useRef<HTMLDivElement>(null);\n\n  const [open, setOpen] =\n    useState(false);\n  const [rows, setRows] =\n    useState<NotificationRow[]>([]);\n  const [muted, setMuted] =\n    useState(false);\n  const [loading, setLoading] =\n    useState(true);\n  const [changingMute, setChangingMute] =\n    useState(false);\n\n  const [panelPosition, setPanelPosition] =\n    useState({\n      top: 0,\n      right: 12,\n    });\n\n  const load = useCallback(\n    async () => {\n      const { data, error } =\n        await supabase.rpc(\n          "get_my_notification_bundle",\n        );\n\n      if (error) {\n        console.warn(\n          "Notifications:",\n          error.message,\n        );\n        setLoading(false);\n        return;\n      }\n\n      const bundle =\n        (data ?? {\n          muted: false,\n          notifications: [],\n        }) as NotificationBundle;\n\n      setMuted(bundle.muted === true);\n      setRows(\n        Array.isArray(\n          bundle.notifications,\n        )\n          ? bundle.notifications\n          : [],\n      );\n      setLoading(false);\n    },\n    [supabase],\n  );\n\n  useEffect(() => {\n    void load();\n\n    const handleAdminDataChanged =\n      () => {\n        void load();\n      };\n\n    window.addEventListener(\n      "sepulchria:admin-data-changed",\n      handleAdminDataChanged,\n    );\n\n    const timer =\n      window.setInterval(\n        () => void load(),\n        60_000,\n      );\n\n    return () => {\n      window.clearInterval(timer);\n      window.removeEventListener(\n        "sepulchria:admin-data-changed",\n        handleAdminDataChanged,\n      );\n    };\n  }, [load, pathname]);\n\n  useEffect(() => {\n    function updatePanelPosition() {\n      const button =\n        buttonRef.current;\n\n      if (!button) return;\n\n      const rect =\n        button.getBoundingClientRect();\n\n      setPanelPosition({\n        top: rect.bottom + 8,\n        right: Math.max(\n          12,\n          window.innerWidth -\n            rect.right,\n        ),\n      });\n    }\n\n    function onMouseDown(\n      event: MouseEvent,\n    ) {\n      if (!open) return;\n\n      const target =\n        event.target as Node;\n\n      if (\n        rootRef.current?.contains(\n          target,\n        ) ||\n        panelRef.current?.contains(\n          target,\n        )\n      ) {\n        return;\n      }\n\n      setOpen(false);\n    }\n\n    if (open) {\n      updatePanelPosition();\n\n      window.addEventListener(\n        "resize",\n        updatePanelPosition,\n      );\n      window.addEventListener(\n        "scroll",\n        updatePanelPosition,\n        true,\n      );\n    }\n\n    document.addEventListener(\n      "mousedown",\n      onMouseDown,\n    );\n\n    return () => {\n      document.removeEventListener(\n        "mousedown",\n        onMouseDown,\n      );\n      window.removeEventListener(\n        "resize",\n        updatePanelPosition,\n      );\n      window.removeEventListener(\n        "scroll",\n        updatePanelPosition,\n        true,\n      );\n    };\n  }, [open]);\n\n  const unreadCount =\n    muted\n      ? 0\n      : rows.filter(\n          (row) => row.is_unread,\n        ).length;\n\n  async function toggle() {\n    const next = !open;\n    setOpen(next);\n\n    if (\n      !next ||\n      muted ||\n      unreadCount === 0\n    ) {\n      return;\n    }\n\n    const { error } =\n      await supabase.rpc(\n        "mark_my_notifications_viewed",\n      );\n\n    if (!error) {\n      setRows((current) =>\n        current.map((row) => ({\n          ...row,\n          is_unread: false,\n        })),\n      );\n    }\n  }\n\n  async function toggleMute() {\n    if (changingMute) return;\n\n    setChangingMute(true);\n\n    const next = !muted;\n\n    const { error } =\n      await supabase.rpc(\n        "set_my_notifications_muted",\n        {\n          p_muted: next,\n        },\n      );\n\n    if (error) {\n      console.warn(\n        "Notification mute:",\n        error.message,\n      );\n      setChangingMute(false);\n      return;\n    }\n\n    setMuted(next);\n\n    if (next) {\n      setRows([]);\n    } else {\n      await load();\n    }\n\n    setChangingMute(false);\n  }\n\n  return (\n    <div\n      ref={rootRef}\n      className="relative"\n    >\n      <button\n        ref={buttonRef}\n        type="button"\n        onClick={() =>\n          void toggle()\n        }\n        aria-label={\n          muted\n            ? "Notifications muted"\n            : `${unreadCount} unread notifications`\n        }\n        aria-expanded={open}\n        title={\n          muted\n            ? "Notifications muted"\n            : "Notifications"\n        }\n        className={[\n          "relative flex h-8 w-8 items-center justify-center border transition sm:h-9 sm:w-9 2xl:h-10 2xl:w-10",\n          muted\n            ? "border-red-900/70 bg-red-950/35 text-red-400 hover:border-red-700/80 hover:text-red-300"\n            : "border-[rgb(var(--sep-colour-614b31))] bg-[rgb(var(--sep-colour-17120f))] text-[rgb(var(--sep-colour-c69b5c))] hover:border-[rgb(var(--sep-colour-977242))] hover:text-[rgb(var(--sep-colour-efd6a3))]",\n        ].join(" ")}\n      >\n        {muted ? (\n          <BellOff className="h-5 w-5" />\n        ) : (\n          <Bell className="h-5 w-5" />\n        )}\n\n        {unreadCount > 0 ? (\n          <span\n            title={`${unreadCount} unread notification${unreadCount === 1 ? "" : "s"}`}\n            aria-label={`${unreadCount} unread notification${unreadCount === 1 ? "" : "s"}`}\n            className="absolute -right-2 -top-2 flex h-5 w-5 items-center justify-center rounded-full border border-[rgb(var(--sep-colour-d19a4c))] bg-[rgb(var(--sep-colour-7a291f))] text-[8px] font-bold leading-none text-[rgb(var(--sep-colour-ffe1ac))] shadow-[0_0_10px_rgba(var(--sep-rgb-209-154-76),0.32)]"\n          >\n            {unreadCount > 9\n              ? "9+"\n              : unreadCount}\n          </span>\n        ) : null}\n      </button>\n\n      {open &&\n      typeof document !==\n        "undefined"\n        ? createPortal(\n            <div\n              ref={panelRef}\n              data-vocabulary-static\n              className="fixed z-[9999] w-[min(390px,calc(100vw-24px))] !translate-x-0 !translate-y-0 !scale-100 !transform-none !animate-none !opacity-100 !transition-none !filter-none border border-[rgb(var(--sep-colour-6e5535))]/70 bg-[rgb(var(--sep-colour-100c09))] shadow-2xl"\n              style={{\n                top: panelPosition.top,\n                right:\n                  panelPosition.right,\n                transform: "none",\n                filter: "none",\n                animation: "none",\n                transition: "none",\n                opacity: 1,\n              }}\n            >\n              <div className="border-b border-[rgb(var(--sep-colour-59432c))]/45 px-4 py-3">\n                <p className="text-[8px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-806b50))]">\n                  Offgame\n                </p>\n\n                <div className="mt-1 flex items-center justify-between gap-3">\n                  <div>\n                    <h2 className="font-serif text-lg text-[rgb(var(--sep-colour-d8bf91))]">\n                      Notifications\n                    </h2>\n\n                    <p\n                      className={[\n                        "mt-0.5 text-[8px] uppercase tracking-[0.14em]",\n                        muted\n                          ? "text-red-400"\n                          : "text-[rgb(var(--sep-colour-756958))]",\n                      ].join(\n                        " ",\n                      )}\n                    >\n                      {muted\n                        ? "Muted"\n                        : `${rows.length} active`}\n                    </p>\n                  </div>\n\n                  <button\n                    type="button"\n                    onClick={() =>\n                      void toggleMute()\n                    }\n                    disabled={\n                      changingMute\n                    }\n                    className={[\n                      "flex items-center gap-1.5 border px-2.5 py-1.5 text-[8px] uppercase tracking-[0.14em] transition disabled:cursor-wait disabled:opacity-50",\n                      muted\n                        ? "border-red-800/70 bg-red-950/30 text-red-300 hover:border-red-600/80 hover:bg-red-950/50"\n                        : "border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-17110d))] text-[rgb(var(--sep-colour-ae9570))] hover:border-[rgb(var(--sep-colour-8a673f))] hover:text-[rgb(var(--sep-colour-dbc091))]",\n                    ].join(\n                      " ",\n                    )}\n                  >\n                    {muted ? (\n                      <>\n                        <Bell className="h-3.5 w-3.5" />\n                        Unmute\n                      </>\n                    ) : (\n                      <>\n                        <BellOff className="h-3.5 w-3.5" />\n                        Mute\n                      </>\n                    )}\n                  </button>\n                </div>\n              </div>\n\n              <div className="max-h-[min(65vh,560px)] overflow-y-auto p-2">\n                {loading ? (\n                  <p className="px-4 py-6 text-center text-xs text-[rgb(var(--sep-colour-8f8271))]">\n                    Loading\n                    notifications...\n                  </p>\n                ) : muted ? (\n                  <div className="border border-red-950/55 bg-red-950/15 px-4 py-6 text-center">\n                    <BellOff className="mx-auto h-5 w-5 text-red-500/80" />\n                    <p className="mt-3 font-serif text-sm text-[rgb(var(--sep-colour-c5aa83))]">\n                      Notifications\n                      are muted.\n                    </p>\n                    <p className="mt-1 text-[10px] leading-5 text-[rgb(var(--sep-colour-7f7466))]">\n                      New notices\n                      will remain\n                      waiting until\n                      you unmute\n                      them.\n                    </p>\n                  </div>\n                ) : rows.length ? (\n                  <div className="space-y-1.5">\n                    {rows.map(\n                      (row) => {\n                        const content =\n                          (\n                            <>\n                              <div className="flex items-start justify-between gap-3">\n                                <span className="text-[7px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-806b50))]">\n                                  {row.type.replaceAll(\n                                    "_",\n                                    " ",\n                                  )}\n                                  {row.is_automatic\n                                    ? " · Auto"\n                                    : ""}\n                                </span>\n\n                                <span className="shrink-0 text-[8px] text-[rgb(var(--sep-colour-6f6252))]">\n                                  {new Date(\n                                    row.starts_at,\n                                  ).toLocaleString()}\n                                </span>\n                              </div>\n\n                              <p className="mt-1 font-serif text-[15px] text-[rgb(var(--sep-colour-d8bf91))]">\n                                {\n                                  row.title\n                                }\n                              </p>\n\n                              <p className="mt-1 text-[11px] leading-5 text-[rgb(var(--sep-colour-a99b89))]">\n                                {\n                                  row.body\n                                }\n                              </p>\n\n                              {row.href ? (\n                                <span className="mt-2 block text-[8px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-b28a53))]">\n                                  Open →\n                                </span>\n                              ) : null}\n                            </>\n                          );\n\n                        const className =\n                          [\n                            "block border px-3 py-3 transition-all duration-150 hover:-translate-y-[1px] hover:border-[rgb(var(--sep-colour-8a673f))] hover:bg-[rgb(var(--sep-colour-17110d))] hover:shadow-[0_0_12px_rgba(var(--sep-rgb-177-132-75),0.08)]",\n                            row.is_unread\n                              ? "border-[rgb(var(--sep-colour-765937))]/55 bg-[rgb(var(--sep-colour-21170f))]"\n                              : "border-[rgb(var(--sep-colour-59432c))]/35 bg-[rgb(var(--sep-colour-100c09))]",\n                          ].join(\n                            " ",\n                          );\n\n                        return row.href ? (\n                          <Link\n                            key={\n                              row.id\n                            }\n                            href={\n                              row.href\n                            }\n                            onClick={() =>\n                              setOpen(\n                                false,\n                              )\n                            }\n                            className={\n                              className\n                            }\n                          >\n                            {\n                              content\n                            }\n                          </Link>\n                        ) : (\n                          <div\n                            key={\n                              row.id\n                            }\n                            className={\n                              className\n                            }\n                          >\n                            {\n                              content\n                            }\n                          </div>\n                        );\n                      },\n                    )}\n                  </div>\n                ) : (\n                  <p className="px-4 py-8 text-center text-xs text-[rgb(var(--sep-colour-8f8271))]">\n                    Nothing to\n                    report.\n                  </p>\n                )}\n              </div>\n            </div>,\n            document.body,\n          )\n        : null}\n    </div>\n  );\n}\n', encoding="utf-8")
print("✓ components/notifications/notification-bell.tsx")

text = context_path.read_text(encoding="utf-8")

pattern = re.compile(
    r'function AdminNotificationsNavigatorContext\(\) \{.*?\n\}\n\n\ntype AdminNavigationEntry',
    re.S,
)

replacement = 'function AdminNotificationsNavigatorContext() {\n  const [entries, setEntries] =\n    useState<AdminNotificationContextEntry[]>([]);\n  const [search, setSearch] =\n    useState("");\n\n  useEffect(() => {\n    let frame: number | null =\n      null;\n\n    const readEntries = () => {\n      frame = null;\n\n      const nodes = Array.from(\n        document.querySelectorAll<HTMLElement>(\n          "[data-admin-notification-id]",\n        ),\n      );\n\n      setEntries(\n        nodes.map((node) => ({\n          id:\n            node.dataset.adminNotificationId ??\n            "",\n          title:\n            node.dataset.adminNotificationTitle ??\n            "Untitled Notification",\n          type:\n            node.dataset.adminNotificationType ??\n            "",\n          body:\n            node.dataset.adminNotificationBody ??\n            "",\n          source:\n            node.dataset.adminNotificationSource ??\n            "",\n          active:\n            node.dataset.adminNotificationActive ===\n            "true",\n        })),\n      );\n    };\n\n    const scheduleRead = () => {\n      if (frame !== null) {\n        window.cancelAnimationFrame(\n          frame,\n        );\n      }\n\n      frame =\n        window.requestAnimationFrame(\n          readEntries,\n        );\n    };\n\n    scheduleRead();\n\n    const observer =\n      new MutationObserver(\n        scheduleRead,\n      );\n\n    observer.observe(\n      document.body,\n      {\n        childList: true,\n        subtree: true,\n        attributes: true,\n        attributeFilter: [\n          "data-admin-notification-title",\n          "data-admin-notification-type",\n          "data-admin-notification-body",\n          "data-admin-notification-source",\n          "data-admin-notification-active",\n        ],\n      },\n    );\n\n    window.addEventListener(\n      "sepulchria:admin-data-changed",\n      scheduleRead,\n    );\n\n    return () => {\n      observer.disconnect();\n\n      if (frame !== null) {\n        window.cancelAnimationFrame(\n          frame,\n        );\n      }\n\n      window.removeEventListener(\n        "sepulchria:admin-data-changed",\n        scheduleRead,\n      );\n    };\n  }, []);\n\n  const query =\n    search\n      .trim()\n      .toLocaleLowerCase();\n\n  const visibleEntries =\n    entries.filter((entry) => {\n      if (!query) {\n        return true;\n      }\n\n      return [\n        entry.title,\n        entry.type,\n        entry.body,\n        entry.source,\n      ]\n        .join(" ")\n        .toLocaleLowerCase()\n        .includes(query);\n    });\n\n  function jumpToNotification(\n    id: string,\n  ) {\n    const target =\n      document.getElementById(\n        `admin-notification-${id}`,\n      );\n\n    if (!target) return;\n\n    if (\n      target instanceof\n      HTMLDetailsElement\n    ) {\n      target.open = true;\n    }\n\n    target.scrollIntoView({\n      behavior: "smooth",\n      block: "start",\n    });\n\n    const oldOutline =\n      target.style.outline;\n    const oldOffset =\n      target.style.outlineOffset;\n\n    target.style.outline =\n      "1px solid rgb(var(--sep-colour-8d6d3e))";\n    target.style.outlineOffset =\n      "3px";\n\n    window.setTimeout(() => {\n      target.style.outline =\n        oldOutline;\n      target.style.outlineOffset =\n        oldOffset;\n    }, 1200);\n  }\n\n  function jumpToNew() {\n    document\n      .getElementById(\n        "notification-new",\n      )\n      ?.scrollIntoView({\n        behavior: "smooth",\n        block: "start",\n      });\n  }\n\n  return (\n    <div className="flex h-full min-h-0 flex-col">\n      <p className="text-[8px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-806b50))]">\n        Notification administration\n      </p>\n\n      <h2 className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-d8bf91))]">\n        Jump to Notification\n      </h2>\n\n      <button\n        type="button"\n        onClick={jumpToNew}\n        className="mt-4 w-full border border-[rgb(var(--sep-colour-765937))]/65 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2.5 text-left text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-d9c092))] transition hover:border-[rgb(var(--sep-colour-a07945))]"\n      >\n        + Create new notification\n      </button>\n\n      <input\n        type="search"\n        value={search}\n        onChange={(event) =>\n          setSearch(\n            event.target.value,\n          )\n        }\n        placeholder="Search notifications..."\n        className="mt-3 w-full border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2.5 text-xs text-[rgb(var(--sep-colour-d4bea0))] outline-none placeholder:text-[rgb(var(--sep-colour-665b4d))] focus:border-[rgb(var(--sep-colour-987344))]"\n      />\n\n      <p className="mb-2 mt-4 text-[8px] uppercase tracking-[.18em] text-[rgb(var(--sep-colour-806b50))]">\n        Notifications · {visibleEntries.length}\n        {query\n          ? ` / ${entries.length}`\n          : ""}\n      </p>\n\n      <div className="min-h-0 flex-1 space-y-1.5 overflow-y-auto pr-1">\n        {visibleEntries.length ? (\n          visibleEntries.map(\n            (entry) => (\n              <button\n                key={entry.id}\n                type="button"\n                onClick={() =>\n                  jumpToNotification(\n                    entry.id,\n                  )\n                }\n                className="group flex w-full items-center justify-between gap-3 border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2.5 text-left transition hover:-translate-y-[1px] hover:border-[rgb(var(--sep-colour-8a673f))] hover:bg-[rgb(var(--sep-colour-17110d))] hover:shadow-[0_0_10px_rgba(var(--sep-rgb-177-132-75),0.06)]"\n              >\n                <span className="min-w-0">\n                  <span className="block truncate font-serif text-[13px] text-[rgb(var(--sep-colour-cbb28a))] group-hover:text-[rgb(var(--sep-colour-ead0a0))]">\n                    {entry.title}\n                  </span>\n\n                  <span className="mt-0.5 block truncate text-[8px] uppercase tracking-[0.12em] text-[rgb(var(--sep-colour-6f6252))]">\n                    {entry.type}\n                    {" · "}\n                    {entry.source}\n                    {" · "}\n                    {entry.active\n                      ? "Active"\n                      : "Disabled"}\n                  </span>\n                </span>\n\n                <span className="shrink-0 text-[rgb(var(--sep-colour-725a3d))]">\n                  →\n                </span>\n              </button>\n            ),\n          )\n        ) : (\n          <p className="text-xs text-[rgb(var(--sep-colour-8f826f))]">\n            No matching notifications.\n          </p>\n        )}\n      </div>\n    </div>\n  );\n}' + "\n\n\ntype AdminNavigationEntry"

text, count = pattern.subn(
    lambda _match: replacement,
    text,
    count=1,
)

if count != 1:
    raise SystemExit(
        f"AdminNotificationsNavigatorContext: expected 1 match, found {count}. "
        f"Expected commit {BASE}."
    )

context_path.write_text(text, encoding="utf-8")
print("✓ components/portal/admin-context-panel.tsx")
print()
print("Notification UI + mute + live admin context patch installed.")
print("Run the SQL expansion first, then npm run build.")
